import React, { useContext, useEffect, useState } from 'react';
import { Alert, Spinner } from 'react-bootstrap';
import { FaArrowLeft, FaCheckCircle, FaFileInvoiceDollar } from 'react-icons/fa';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../../App';
import { fetchStudentFeeSummary } from '../../services/FeeServices/feeServices';

const money = (value) => `₹${Number(value || 0).toLocaleString('en-IN')}`;

function StudentFeeSummary() {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth.user || {};
  const navigate = useNavigate();
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const load = async () => {
      if (!user.stdid || !user.instid || !user.brcid || !user.acdmcyr) {
        setError('Student fee information is unavailable.');
        setLoading(false);
        return;
      }
      const response = await fetchStudentFeeSummary({
        stdid: user.stdid, instid: user.instid, brcid: user.brcid, acdmcyr: user.acdmcyr,
      });
      if (response?.status === 'success') setSummary(response.payload);
      else setError(response?.error?.message || response?.errors?.[0]?.errorMessage || 'Unable to load fee details.');
      setLoading(false);
    };
    load();
  }, [user.stdid, user.instid, user.brcid, user.acdmcyr]);

  return <main className="fee-summary-page">
    <header className="fee-summary-header">
      <button type="button" onClick={() => navigate('/dashboard')} aria-label="Back"><FaArrowLeft /></button>
      <div><h1>Fee Details</h1><p>Academic year {user.acdmcyr || ''}</p></div>
    </header>
    {loading && <div className="fee-summary-state"><Spinner animation="border" /> Loading fee details…</div>}
    {!loading && error && <Alert variant="danger">{error}</Alert>}
    {!loading && summary && <>
      <section className="fee-total-card"><span>Total pending</span><strong>{money(summary.total_pending)}</strong><div><span>Payable {money(summary.total_payable)}</span><span>Paid {money(summary.total_paid)}</span></div></section>
      <section className="fee-category-list">{summary.fees.map((fee) =>
        <article className="fee-category-card" key={fee.type}>
          <div className={`fee-category-icon ${fee.status.toLowerCase()}`}>{fee.status === 'PAID' ? <FaCheckCircle /> : <FaFileInvoiceDollar />}</div>
          <div className="fee-category-content"><div className="fee-category-title"><h2>{fee.label}</h2><span className={fee.status.toLowerCase()}>{fee.status}</span></div>
            <div className="fee-category-values"><span>Payable <b>{money(fee.payable)}</b></span><span>Paid <b>{money(fee.paid)}</b></span><span>Pending <b>{money(fee.pending)}</b></span></div>
            {fee.discount > 0 && <small>Discount: {money(fee.discount)}</small>}
          </div>
        </article>)}</section>
    </>}
  </main>;
}

export default StudentFeeSummary;
